    const s = cartReducer({ items: { a: 1 } }, { type: 'remove', sku: 'a' });
    expect(s.items.a).toBeUndefined();
  });
  it('acao desconhecida devolve equivalente', () => {
    const s = cartReducer({ items: { a: 2 } }, { type: 'noop', sku: 'a' });
    expect(s.items).toEqual({ a: 2 });
  });
});

