export function cartReducer(state: any, action: any): any {
  const items = { ...state.items };
  if (action.type === 'add') {
    items[action.sku] = (items[action.sku] || 0) + 1;
  } else if (action.type === 'remove') {
    const cur = (items[action.sku] || 0) - 1;
    if (cur > 0) { items[action.sku] = cur; } else { delete items[action.sku]; }
  }
  return { items };
}

